<script module lang="ts">
/**
 * The overview screen (`design/archetypes/dashboard.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/dashboard.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { SlotOutlet, SlotScope, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/archetypes/dashboard.module.css'
import Card from '../structure/Card.svelte'
import PageHeader from '../structure/PageHeader.svelte'
import Stat from '../structure/Stat.svelte'
import type { StatProps } from '../structure/Stat.svelte'

export interface DashboardProps {
  /**
   * Header actions, which most dashboards do not have because they only display data.
   */
  actions?: Snippet
  description?: string
  /**
   * The main column.
   */
  primary: Snippet
  /**
   * The narrow column. Omit and `primary` spans the full width.
   */
  secondary?: Snippet
  /**
   * Two to four stats, because more than four belong in a table.
   */
  stats?: StatProps[]
  title: string
  /**
   * PageHeader's: an InlineEdit of the title, for an overview of one thing the reader names,
   * such as an environment.
   */
  titleEdit?: Snippet
}
</script>

<script lang="ts">
let { actions, description, primary, secondary, stats, title, titleEdit }: DashboardProps = $props()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get actions() {
    return actions
  },
  get primary() {
    return primary
  },
  get secondary() {
    return secondary
  },
  get titleEdit() {
    return titleEdit
  },
}
const titleEditScope: SlotScope = new SlotScope({
  pass: (): Record<string, unknown> => ({ valueHidden: true }),
})
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div class={styles.page} data-member="dashboard"
    >{#snippet titleEditOfPageHeader1()
      }<SlotOutlet scope={titleEditScope} snippet={titleEdit}
    />{/snippet
    }{#snippet actionsOfPageHeader2()}{@render actions?.()}{/snippet
    }<PageHeader
      {title}
      {description}
      titleEdit={slots.titleEdit ? titleEditOfPageHeader1 : undefined}
      actions={slots.actions ? actionsOfPageHeader2 : undefined}
    />{#if stats !== undefined && stats.length > 0
      }<div class={styles.stats} data-count={String(stats.length)}
        >{#each stats as stat, at (`${at}-${stat.label}`)
          }<Card
            ><Stat
              label={stat.label}
              value={stat.value}
              numeric={stat.numeric}
              icon={stat.icon}
              delta={stat.delta}
              trend={stat.trend}
              spark={stat.spark}
              sparkLabel={stat.sparkLabel}
              description={stat.description}
              footer={stat.footer}
          /></Card
        >{/each
      }</div
    >{/if
    }<div class={styles.body} data-secondary={(slots.secondary) ? '' : undefined}
      ><div class={styles.primary}>{@render primary?.()}</div
      >{#if slots.secondary}<div class={styles.secondary}>{@render secondary?.()}</div>{/if
    }</div
  ></div
>{/if
}{@render joined.end?.()}
